const DAY = 86_400_000;
const toMs = (value: ConversationItem['updatedAt']): number | undefined => {
  if (value === undefined) return undefined;
  const ms = value instanceof Date ? value.getTime() : typeof value === 'number' ? value : Date.parse(value);
  return Number.isFinite(ms) ? ms : undefined;
};

/** Short relative time for a list row: "now", "5m", "3h", "Yesterday", "4d", then a date. */
export function relativeTime(value: ConversationItem['updatedAt'], now = Date.now(), labels: Pick<ChatLabels, 'justNow' | 'yesterday'> = defaultChatLabels): string {
  const ms = toMs(value);
  if (ms === undefined) return '';
  const age = Math.max(0, now - ms);
  if (age < 60_000) return labels.justNow;
  if (age < 3_600_000) return `${Math.floor(age / 60_000)}m`;
  if (age < DAY) return `${Math.floor(age / 3_600_000)}h`;
  const days = Math.floor(age / DAY);
  if (days === 1) return labels.yesterday;
  if (days < 7) return `${days}d`;
  return new Date(ms).toLocaleDateString(undefined, { month: 'short', day: 'numeric', ...(days > 300 ? { year: 'numeric' } : {}) });
}

type Group = 'today' | 'yesterday' | 'previousWeek' | 'older' | 'conversations';
function groupOf(value: ConversationItem['updatedAt'], now: number): Group {
  const ms = toMs(value);
  if (ms === undefined) return 'conversations';
  const start = new Date(now); start.setHours(0, 0, 0, 0);
  const age = start.getTime() - ms;
  return age <= 0 ? 'today' : age <= DAY ? 'yesterday' : age < 7 * DAY ? 'previousWeek' : 'older';
}
const ORDER: readonly Group[] = ['today', 'yesterday', 'previousWeek', 'older', 'conversations'];

/** The row's "…" menu: host actions in the consumer's shadcn dropdown-menu. */
function RowActions({ label, items }: { readonly label: string; readonly items: readonly MenuItem[] }) {
  const portal = useRef<HTMLElement | null>(null);
  return <DropdownMenu>
    <DropdownMenuTrigger render={<Button ref={node => { portal.current = node?.ownerDocument.body ?? null; }} variant="ghost" size="icon-sm" aria-label={label} title={label} data-testid="conversation-action-more"><EllipsisIcon data-icon="inline-start" aria-hidden="true" /></Button>} />
    <DropdownMenuPortal container={portal}>
      <DropdownMenuContent align="end" aria-label={label} data-testid="conversation-action-more-list" className="w-64 max-w-[calc(100vw-1rem)]">
        {items.map(item => <Fragment key={item.id}>
          {item.separatorBefore && <DropdownMenuSeparator />}
          <DropdownMenuItem variant={item.destructive ? 'destructive' : 'default'} disabled={item.disabled} data-testid={item.testId ?? `conversation-action-more-${item.id}`} data-item={item.id} onClick={item.onSelect} className="min-h-8 max-sm:min-h-10 pointer-coarse:min-h-10">
            {item.icon}{item.label}
          </DropdownMenuItem>
        </Fragment>)}
      </DropdownMenuContent>
    </DropdownMenuPortal>
  </DropdownMenu>;
}

/**
 * The searchable list of past conversations: a search box (server-side when the host offers `search`), the Archived filter, rows grouped by
 * recency with the open one marked, and the row actions the host offers (rename, archive, delete). It fills its container; `ConversationHistory`
 * puts it in a popover or sheet, the `pi-app` block in its sessions pane. `onPicked` runs after a row is chosen.
 */
export function ConversationList({ conversations, onPicked, autoFocus = false, searchMode = 'disclosure', rowActionLayout = 'menu', navigation }: {
  readonly conversations: ConversationsConfig;
  /** `inline` retains the always-visible search field. */
  readonly searchMode?: 'disclosure' | 'inline';
  /** `inline` retains the separate rename/archive/delete buttons. */
  readonly rowActionLayout?: 'menu' | 'inline';
  readonly navigation?: ReactNode;
  readonly onPicked?: (() => void) | undefined;
  /** Focus the search box on mount (not on touch screens). */
  readonly autoFocus?: boolean;
}) {
  const { labels } = useChatText();
  const [query, setQuery] = useState('');
  const [searchOpen, setSearchOpen] = useState(autoFocus || searchMode === 'inline');
  const [archived, setArchived] = useState(false);
  // Server-side results while a query is typed or the Archived filter is on (when the host offers `search`).
  const [found, setFound] = useState<{ readonly items: readonly ConversationItem[]; readonly loading: boolean } | null>(null);
  const [revision, setRevision] = useState(0);
  const [renaming, setRenaming] = useState<string | null>(null);
  const [confirming, setConfirming] = useState<string | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const search = useRef<HTMLInputElement>(null);
  const now = useMemo(() => Date.now(), [conversations.items]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (autoFocus && !globalThis.matchMedia?.('(pointer: coarse)').matches) search.current?.focus(); }, [autoFocus]);
  const serverSearch = conversations.search;
  useEffect(() => {
    const needle = query.trim();
    if (!serverSearch || (!needle && !archived)) { setFound(null); return; }
    const controller = new AbortController();
    setFound(previous => ({ items: previous?.items ?? [], loading: true }));
    const timer = setTimeout(() => {
      serverSearch(needle, { archived }, controller.signal).then(items => { if (!controller.signal.aborted) setFound({ items, loading: false }); })
        .catch(() => { if (!controller.signal.aborted) setFound({ items: [], loading: false }); });
    }, 150);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [serverSearch, query, archived, revision]);
  /** Runs one row action; the host refreshes `items`, and a server-side search runs again. */
  const run = (action: () => Promise<void>) => {
    setFailure(null);
    action().then(() => setRevision(value => value + 1), () => setFailure(labels.actionFailed));
  };
  const shown = useMemo(() => {
    const needle = query.trim().toLowerCase();
    const items = found ? found.items : conversations.items.filter(item => !item.archived && (!needle || (item.title ?? labels.untitled).toLowerCase().includes(needle)));
    const sorted = [...items].sort((a, b) => (toMs(b.updatedAt) ?? 0) - (toMs(a.updatedAt) ?? 0));
    const groups = new Map<Group, ConversationItem[]>();
    for (const item of sorted) { const key = groupOf(item.updatedAt, now); groups.set(key, [...(groups.get(key) ?? []), item]); }
    return ORDER.flatMap(key => groups.has(key) ? [{ key, items: groups.get(key)! }] : []);
  }, [conversations.items, found, query, now, labels.untitled]);
  const loading = found ? found.loading : conversations.loading;
  const total = shown.reduce((sum, group) => sum + group.items.length, 0);
  const rowActionItems = (item: ConversationItem, extraButtons: readonly BlockAction[], extraMenu: readonly BlockAction[]): MenuItem[] => [
    ...(conversations.rename ? [{ id: 'rename', icon: <PencilIcon />, label: labels.rename, testId: 'conversation-rename', onSelect: () => setRenaming(item.id) }] : []),
    ...(conversations.archive ? [{ id: 'archive', icon: item.archived ? <ArchiveRestoreIcon /> : <ArchiveIcon />, label: item.archived ? labels.restore : labels.archive, testId: 'conversation-archive', onSelect: () => run(() => conversations.archive!(item.id, !item.archived)) }] : []),
    ...(conversations.remove ? [{ id: 'delete', icon: <Trash2Icon />, destructive: true, separatorBefore: true, label: labels.delete, testId: 'conversation-delete', onSelect: () => setConfirming(item.id) }] : []),
    ...[...extraButtons, ...extraMenu].map(entry => actionMenuItem(entry, 'conversation-action')),
  ];
  return <>
      {!searchOpen && <Button variant="ghost" data-testid="conversation-search-open" className="mx-2 justify-start" onClick={() => { setSearchOpen(true); requestAnimationFrame(() => search.current?.focus()); }}><SearchIcon data-icon="inline-start" aria-hidden="true" />{labels.search}</Button>}
      {searchOpen && <div className="shrink-0 px-3 py-2">
        <InputGroup>
          <InputGroupAddon><SearchIcon aria-hidden="true" /></InputGroupAddon>
          <InputGroupInput ref={search} type="search" value={query} onChange={event => setQuery(event.currentTarget.value)} placeholder={labels.searchConversations} aria-label={labels.searchConversations} data-testid="conversation-search" />
          {conversations.archive && serverSearch && <InputGroupAddon align="inline-end"><Toggle pressed={archived} aria-label={labels.archived} title={labels.archived} data-testid="conversations-archived"
            onPressedChange={setArchived}><ArchiveIcon data-icon="inline-start" aria-hidden="true" />{labels.archived}</Toggle></InputGroupAddon>}
        </InputGroup>
      </div>}
      {navigation}
      {failure && <p role="alert" className="m-0 shrink-0 px-3 pt-2 text-xs text-destructive">{failure}</p>}
      <ScrollArea className="min-h-0 flex-1" aria-busy={loading ? 'true' : undefined}>
        {total === 0 && <p role="status" data-testid="conversations-empty" className="m-0 px-3 py-8 text-center text-sm text-muted-foreground">
          {loading ? labels.loadingConversations : query.trim() ? labels.noMatch(query.trim()) : archived ? labels.noArchived : labels.noConversations}</p>}
        {shown.map(group => <SidebarGroup key={group.key} aria-label={labels[group.key]} role="group">
          <SidebarGroupLabel render={<h4 />}>{labels[group.key]}</SidebarGroupLabel>
          <SidebarMenu>
            {group.items.map(item => {
              const active = item.id === conversations.activeId;
              const title = item.title?.trim() || labels.untitled;
              const extra = conversations.rowActions?.(item);
              // A row has room for icons only: a header action without an icon goes in the row's "…" menu.
              const extraButtons = headerActions(extra).filter(entry => entry.icon), extraMenu = [...headerActions(extra).filter(entry => !entry.icon), ...menuActions(extra)];
              if (renaming === item.id && conversations.rename) {
                const rename = conversations.rename;
                return <SidebarMenuItem key={item.id}>
                  <form className="flex items-center gap-2" onSubmit={event => {
                    event.preventDefault();
                    const value = new FormData(event.currentTarget).get('title')?.toString().trim();
                    setRenaming(null);
                    if (value && value !== item.title) run(() => rename(item.id, value));
                  }}>
                    <PencilIcon className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
                    <Input name="title" autoFocus defaultValue={title} maxLength={200} aria-label={labels.conversationName} data-testid="conversation-rename-input"
                      onKeyDown={event => { if (event.key === 'Escape') { event.stopPropagation(); setRenaming(null); } }}
                      className="min-w-0 flex-1" />
                    <Button type="submit" size="sm" variant="outline" data-testid="conversation-rename-save">{labels.save}</Button>
                  </form>
                </SidebarMenuItem>;
              }
              return <SidebarMenuItem key={item.id} className="flex items-center gap-0.5">
                <Button type="button" variant={active ? 'secondary' : 'ghost'} data-testid="conversation-row" data-conversation-id={item.id} data-active={active ? 'true' : undefined} aria-current={active ? 'true' : undefined}
                  title={item.lastMessage ?? undefined}
                  onClick={() => { if (!active) conversations.onSelect(item.id); onPicked?.(); }}
                  className="h-auto min-h-10 min-w-0 flex-1 justify-start max-sm:min-h-12">
                  <MessageSquareIcon data-icon="inline-start" aria-hidden="true" />
                  <span className="min-w-0 flex-1 truncate text-left">{title}</span>
                  {active ? <span className="inline-flex shrink-0 items-center gap-1 text-xs text-muted-foreground"><CheckIcon className="size-3.5" aria-hidden="true" /><span className="sr-only">{labels.current}</span></span>
                    : <span className="shrink-0 text-xs text-muted-foreground tabular-nums">{relativeTime(item.updatedAt, now, labels)}</span>}
                </Button>
                {(conversations.rename || conversations.archive || conversations.remove || extraButtons.length > 0 || extraMenu.length > 0) && <div data-testid="conversation-actions"
                  className={cn('flex shrink-0 items-center gap-0.5', confirming === item.id ? '' : 'opacity-0 group-hover/menu-item:opacity-100 group-focus-within/menu-item:opacity-100 pointer-coarse:opacity-100')}>
                  {confirming === item.id && conversations.remove ? <>
                    <Button size="sm" variant="destructive" data-testid="conversation-delete-confirm" onClick={() => { const remove = conversations.remove!; setConfirming(null); run(() => remove(item.id)); }}>{labels.delete}</Button>
                    <Button size="icon-sm" variant="ghost" aria-label={labels.keep} title={labels.keep} onClick={() => setConfirming(null)}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>
                  </> : rowActionLayout === 'menu' ? <RowActions label={labels.moreActions} items={rowActionItems(item, extraButtons, extraMenu)} /> : <>
                    {conversations.rename && <Button size="icon-sm" variant="ghost" aria-label={labels.renameItem(title)} title={labels.rename} data-testid="conversation-rename" onClick={() => setRenaming(item.id)}><PencilIcon data-icon="inline-start" aria-hidden="true" /></Button>}
                    {conversations.archive && <Button size="icon-sm" variant="ghost" aria-label={labels.archiveItem(title, item.archived === true)} title={item.archived ? labels.restore : labels.archive} data-testid="conversation-archive"
                      onClick={() => { const archive = conversations.archive!; run(() => archive(item.id, !item.archived)); }}>{item.archived ? <ArchiveRestoreIcon data-icon="inline-start" aria-hidden="true" /> : <ArchiveIcon data-icon="inline-start" aria-hidden="true" />}</Button>}
                    {conversations.remove && <Button size="icon-sm" variant="ghost" aria-label={labels.deleteItem(title)} title={labels.delete} data-testid="conversation-delete" onClick={() => setConfirming(item.id)}><Trash2Icon data-icon="inline-start" aria-hidden="true" /></Button>}
                    {extraButtons.map(entry => <ActionButton key={entry.id} action={entry} testId="conversation-action" />)}
                    {extraMenu.length > 0 && <RowActions label={labels.moreActions} items={extraMenu.map(entry => actionMenuItem(entry, 'conversation-action'))} />}
                  </>}
                </div>}
              </SidebarMenuItem>;
            })}
          </SidebarMenu>
        </SidebarGroup>)}
      </ScrollArea>
  </>;
}

/**
 * The list of past conversations in a dialog: a header with New, then `ConversationList`.
 * An anchored card on a wide screen and a bottom drawer on a phone. Escape or a click outside closes it.
 */
export function ConversationHistory({ conversations, onClose, placement = 'below' }: {
  readonly conversations: ConversationsConfig;
  readonly onClose: () => void;
  /** `above` opens the card upwards from a bar docked at the bottom of the screen; the backdrop then covers the whole page. */
  readonly placement?: 'below' | 'above';
}) {
  const { labels, icons } = useChatText();
  const [phone, setPhone] = useState(() => globalThis.matchMedia?.('(max-width: 640px)').matches === true);
  useEffect(() => { const media = globalThis.matchMedia?.('(max-width: 640px)'); if (!media) return; const change = () => setPhone(media.matches); media.addEventListener('change', change); return () => media.removeEventListener('change', change); }, []);
  useEffect(() => {
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [onClose]);
  const content = <>
      <header className="flex shrink-0 items-center gap-2 px-3 py-2.5 max-sm:pt-[max(0.625rem,env(safe-area-inset-top))]">
        <Button size="icon-sm" variant="ghost" aria-label={labels.closeHistory} title={labels.close} data-testid="conversations-close" onClick={onClose} className="sm:hidden"><ArrowLeftIcon data-icon="inline-start" aria-hidden="true" /></Button>
        <h3 className="m-0 min-w-0 flex-1 text-sm font-semibold">{labels.history}</h3>
        {conversations.onNew && <Button size="sm" variant="outline" data-testid="conversation-new" onClick={() => { conversations.onNew!(); onClose(); }}><icons.newChat data-icon="inline-start" aria-hidden="true" />{labels.newConversation}</Button>}
        <Button size="icon-sm" variant="ghost" aria-label={labels.closeHistory} title={labels.close} onClick={onClose} className="max-sm:hidden"><XIcon data-icon="inline-start" aria-hidden="true" /></Button>
      </header>
      <Separator />
      <ConversationList conversations={conversations} onPicked={onClose} autoFocus />
  </>;
  return phone ? <Drawer open showSwipeHandle onOpenChange={next => { if (!next) onClose(); }}><DrawerContent data-testid="conversations" aria-label={labels.historyDialog} className="pi-chat min-h-[80dvh]"><DrawerTitle className="sr-only">{labels.historyDialog}</DrawerTitle><div className="flex min-h-0 flex-1 flex-col pb-[env(safe-area-inset-bottom)]">{content}</div></DrawerContent></Drawer>
    : <Popover open onOpenChange={next => { if (!next) onClose(); }} modal={false}>
      <PopoverTrigger nativeButton={false} render={<span aria-hidden="true" className={cn('pointer-events-none absolute', placement === 'above' ? 'bottom-0 left-0' : 'top-12 right-3')} />} />
      <PopoverContent role="dialog" aria-label={labels.historyDialog} data-testid="conversations" side={placement === 'above' ? 'top' : 'bottom'} align={placement === 'above' ? 'start' : 'end'} className="pi-chat w-[23rem] max-w-[calc(100vw-1rem)] max-h-[min(34rem,70dvh)]">{content}</PopoverContent>
    </Popover>;
}

/** The only history chrome inside the normal transcript: a sentinel, spinner and accessible fallback. */
export function TranscriptHistory({ history, connected, onLoad, sentinelRef, hidden, loaded }: {
  readonly history: ChatHistoryState;
  readonly connected: boolean;
  readonly onLoad: () => void;
  readonly sentinelRef: (element: HTMLDivElement | null) => void;
  readonly hidden: number;
  readonly loaded: number;
}) {
  const { labels } = useChatText();
  if (history.kind === 'disabled' && hidden === 0) return null;
  const exhausted = hidden === 0 && history.kind === 'ready' && !history.hasMore;
  return <div ref={sentinelRef} data-testid="transcript-history" className="flex min-h-8 shrink-0 items-center justify-center text-xs text-muted-foreground">
    <Button variant="ghost" data-testid="transcript-history-load" className="sr-only focus:not-sr-only" disabled={!connected || history.kind === 'loading' || exhausted} onClick={onLoad}>{labels.loadEarlierMessages}</Button>
    {history.kind === 'loading' && <Loader2Icon className="size-4 animate-spin motion-reduce:animate-none" aria-label={labels.loadingShort} />}
    {history.kind === 'error' && <span role="alert">{labels.historyFailed}</span>}
    {exhausted && <span>{labels.beginning}</span>}
    <span role="status" aria-live="polite" className="sr-only">{loaded > 0 ? labels.earlierMessagesLoaded(loaded) : ''}</span>
  </div>;
}

'use client';

import { createElement, Fragment, memo, useMemo } from 'react';
import type { ReactNode } from 'react';
import { Marked } from 'marked';
import { decodeHTML } from 'entities';
import { CodeBlock } from './code-block';
import { useChatText } from './labels';
import type { ChatLabels } from './labels';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';

/*
 * Safe Markdown for model output. Tokens are mapped to React elements one by one: raw HTML is shown as text, images are
 * shown as their alt text (nothing is fetched), and a link is only rendered when it is a plain http(s) URL.
 * Ported from the v4 `@hachej/boring-ui-kit` chat markdown renderer; the styling is Tailwind and fenced code gets a code block card.
 */
export interface CommandMention { readonly name: string; readonly behavior: 'execute' | 'insert' }
export interface CommandMentions {
  readonly commands: readonly CommandMention[];
  readonly onActivate: (command: CommandMention) => void;
}

const markdown = new Marked({ gfm: true, breaks: false, pedantic: false });

function isRecord(value: unknown): value is Record<string, unknown> { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function text(value: unknown): string { return typeof value === 'string' ? value : ''; }
function visible(value: unknown): string {
  if (!isRecord(value)) return '';
  if (value['type'] === 'br') return '\n';
  if (Array.isArray(value['tokens'])) return value['tokens'].map(visible).join('');
  const content = text(value['text']);
  return value['type'] === 'text' && value['escaped'] !== true ? decodeHTML(content) : content;
}
function containsHtml(value: unknown): boolean {
  if (!isRecord(value)) return false;
  return value['type'] === 'html' || Array.isArray(value['tokens']) && value['tokens'].some(containsHtml);
}
function literal(value: string): ReactNode { return <span className="whitespace-pre-wrap">{value}</span>; }

interface Context { readonly mentions: CommandMentions | undefined; readonly onCopy: ((text: string) => Promise<void>) | undefined; readonly labels: ChatLabels }

function children(value: unknown, context: Context, before = '', after = '', inline = false): ReactNode {
  if (!Array.isArray(value)) return null;
  if (!context.mentions) return value.map((token: unknown, index) => <Fragment key={index}>{renderToken(token, context)}</Fragment>);
  const shown = value.map(visible), source = before + shown.join('') + after;
  const active = inline && value.some(containsHtml) ? { ...context, mentions: undefined } : context;
  let position = before.length;
  return value.map((token: unknown, index) => {
    const start = position;
    position += shown[index]?.length ?? 0;
    return <Fragment key={index}>{renderToken(token, active, source.slice(0, start), source.slice(position))}</Fragment>;
  });
}

const mentionPattern = /(^|[\s(\[{"'“‘])\/([A-Za-z0-9_][A-Za-z0-9_-]*)(?=$|\s|[.,;!?)}\]"'”’]+(?=$|\s))/g;
function mentionText(value: string, mentions: CommandMentions | undefined, before: string, after: string, labels: ChatLabels): ReactNode {
  if (!mentions?.commands.length || !value.includes('/')) return value;
  const commands = new Map(mentions.commands.filter(item => /^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(item.name)
    && (item.behavior === 'execute' || item.behavior === 'insert')).map(item => [item.name, item]));
  if (!commands.size) return value;
  const source = before + value + after, start = before.length, end = start + value.length;
  const pieces: ReactNode[] = [];
  let cursor = 0;
  for (const match of source.matchAll(mentionPattern)) {
    if (match.index === undefined) continue;
    const boundary = match[1] ?? '', name = match[2];
    if (!name) continue;
    const offset = match.index + boundary.length, limit = offset + name.length + 1;
    const command: CommandMention | undefined = commands.get(name);
    if (!command || offset < start || limit > end || offset - start < cursor) continue;
    const selected = { name: command.name, behavior: command.behavior };
    const at = offset - start;
    if (at > cursor) pieces.push(value.slice(cursor, at));
    pieces.push(<Button key={at} variant="secondary" size="sm" data-testid="command-mention" aria-label={labels.runCommand(selected.name, selected.behavior === 'execute')}
      onClick={() => mentions.onActivate(selected)}>/{selected.name}</Button>);
    cursor = limit - start;
  }
  if (!pieces.length) return value;
  if (cursor < value.length) pieces.push(value.slice(cursor));
  return pieces;
}

function linkTarget(value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined;
  const decoded = decodeHTML(value);
  if (!/^https?:\/\//i.test(decoded) || /[\u0000- \u007f-\u009f\\]/.test(decoded)) return undefined;
  const authority = /^https?:\/\/([^/?#]*)/i.exec(decoded)?.[1];
  if (!authority || authority.includes('@')) return undefined;
  try {
    const url = new URL(decoded);
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) return undefined;
    return url.href;
  } catch { return undefined; }
}

function cells(value: unknown, header: boolean, context: Context): ReactNode {
  if (!Array.isArray(value)) return null;
  return value.map((cell: unknown, index) => {
    if (!isRecord(cell)) return null;
    const alignment = cell['align'];
    const textAlign = alignment === 'left' || alignment === 'center' || alignment === 'right' ? alignment : undefined;
    return createElement(header ? TableHead : TableCell, { key: index, style: { textAlign }, ...(header ? { scope: 'col' } : {}) },
      children(cell['tokens'], context, '', '', true));
  });
}

const HEADINGS: Record<number, string> = {
  1: 'mt-6 mb-2 text-xl font-semibold tracking-tight', 2: 'mt-5 mb-2 text-base font-semibold tracking-tight', 3: 'mt-4 mb-1.5 text-sm font-semibold',
  4: 'mt-4 mb-1 text-sm font-semibold', 5: 'mt-3 mb-1 text-sm font-medium', 6: 'mt-3 mb-1 text-sm font-medium text-muted-foreground',
};

// Marked's extension token includes arbitrary fields. Narrow those fields here before creating React nodes.
function renderToken(value: unknown, context: Context, before = '', after = ''): ReactNode {
  if (!isRecord(value)) return null;
  const raw = text(value['raw']), content = text(value['text']), mentions = context.mentions;
  switch (value['type']) {
    case 'space': case 'def': return null;
    case 'paragraph': return <p className="my-3 first:mt-0 last:mb-0">{children(value['tokens'], context, '', '', true)}</p>;
    case 'heading': {
      const depth = value['depth'];
      return typeof depth === 'number' && Number.isInteger(depth) && depth >= 1 && depth <= 6
        ? createElement(`h${depth}`, { className: `${HEADINGS[depth]} first:mt-0` }, children(value['tokens'], context, '', '', true)) : literal(raw);
    }
    case 'text': return Array.isArray(value['tokens']) ? children(value['tokens'], context, before, after, true)
      : value['escaped'] === true ? literal(content) : mentionText(decodeHTML(content), mentions, before, after, context.labels);
    case 'escape': return content;
    case 'strong': return <strong className="font-semibold text-foreground">{children(value['tokens'], context, before, after, true)}</strong>;
    case 'em': return <em>{children(value['tokens'], context, before, after, true)}</em>;
    case 'del': return <del className="text-muted-foreground">{children(value['tokens'], context, before, after, true)}</del>;
    case 'blockquote': return <blockquote className="my-3 px-4 py-2 text-muted-foreground [&_p]:my-1">{children(value['tokens'], context)}</blockquote>;
    case 'br': return <br />;
    case 'hr': return <hr className="my-5 border-border" />;
    case 'codespan': return <code className="bg-muted px-1.5 py-0.5 font-mono text-sm whitespace-pre-wrap">{content}</code>;
    case 'code': return <CodeBlock code={content} {...(typeof value['lang'] === 'string' && value['lang'] ? { language: value['lang'] } : {})} {...(context.onCopy ? { onCopy: context.onCopy } : {})} />;
    case 'html': return value['block'] === true ? <pre className="my-3 overflow-x-auto font-mono text-xs whitespace-pre-wrap">{raw}</pre> : literal(raw);
    case 'image': return literal(decodeHTML(content) || raw);
    case 'link': {
      const href = linkTarget(value['href']), title = typeof value['title'] === 'string' ? decodeHTML(value['title']) : undefined;
      return href ? <a href={href} title={title} target="_blank" rel="noopener noreferrer"
        className="font-medium text-foreground underline decoration-muted-foreground/50 underline-offset-4 hover:decoration-foreground">{children(value['tokens'], context)}</a> : children(value['tokens'], context);
    }
    case 'list': {
      const start = value['start'];
      return value['ordered'] === true
        ? <ol start={typeof start === 'number' && Number.isSafeInteger(start) ? start : undefined} className="my-3 list-decimal ps-6 marker:text-muted-foreground">{children(value['items'], context)}</ol>
        : <ul className="my-3 list-disc ps-6 marker:text-muted-foreground">{children(value['items'], context)}</ul>;
    }
    case 'list_item': return <li className="ps-1 [&+li]:mt-1 [&>p]:my-1 [&>ol]:my-1 [&>ul]:my-1">{children(value['tokens'], context, '', '', true)}</li>;
    case 'checkbox': return <Checkbox className="inline-flex" checked={value['checked'] === true} disabled aria-label={context.labels.taskStatus} />;
    case 'table': return <Table>
      <TableHeader><TableRow>{cells(value['header'], true, context)}</TableRow></TableHeader>
      <TableBody>{Array.isArray(value['rows']) ? value['rows'].map((row: unknown, index) => <TableRow key={index}>{cells(row, false, context)}</TableRow>) : null}</TableBody></Table>;
    default: return literal(raw);
  }
}

/** One top-level block; unchanged blocks skip re-rendering while a long answer streams. */
const Block = memo(function Block({ token, context }: { readonly token: unknown; readonly context: Context }) {
  return <>{renderToken(token, context)}</>;
}, (a, b) => isRecord(a.token) && isRecord(b.token) && a.token['raw'] === b.token['raw'] && a.token['type'] === b.token['type'] && a.context.mentions === b.context.mentions && a.context.onCopy === b.context.onCopy && a.context.labels === b.context.labels);

export const Markdown = memo(function Markdown({ text: source, commandMentions, onCopy, streaming = false }: {
  readonly text: string; readonly commandMentions?: CommandMentions; readonly onCopy?: (text: string) => Promise<void>; readonly streaming?: boolean;
}) {
  const tokens = useMemo(() => { try { return markdown.lexer(source); } catch { return null; } }, [source]);
  const mentions = source.includes('/') && commandMentions?.commands.length ? commandMentions : undefined;
  const { labels } = useChatText();
  const context = useMemo<Context>(() => ({ mentions, onCopy, labels }), [mentions, onCopy, labels]);
  const body = useMemo(() => {
    if (!tokens) return literal(source);
    // With mentions enabled, positions are relative to the whole text, so render the token list as one unit.
    if (mentions) return children(tokens, context);
    return tokens.map((token, index) => <Block key={index} token={token} context={context} />);
  }, [tokens, source, mentions, context]);
  return <div data-testid="message-text" data-streaming={streaming ? 'true' : undefined} className="min-w-0 [overflow-wrap:anywhere]">
    {body}
  </div>;
});

'use client';

import { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { FileTextIcon, FolderIcon } from 'lucide-react';
import { Item, ItemContent, ItemDescription, ItemMedia, ItemTitle } from '@/components/ui/item';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { usePickerKeyboard } from './picker-keyboard';
import type { MentionResult, MentionsConfig } from './config';
import { useChatText } from './labels';

/**
 * The host's shadcn Popover above the composer, anchored to the nearest positioned ancestor's top edge and as wide as it.
 * Focus stays in the message box (the picker keyboard drives the rows); outside presses dismiss it.
 */
export function ComposerSuggestions({ testId, onDismiss, children }: { readonly testId: string; readonly onDismiss: () => void; readonly children: ReactNode }) {
  return <Popover open modal={false} onOpenChange={open => { if (!open) onDismiss(); }}>
    <PopoverTrigger nativeButton={false} render={<span aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0" />} />
    <PopoverContent data-testid={testId} side="top" align="start" initialFocus={false} finalFocus={false} className="pi-chat w-(--anchor-width) max-w-[calc(100vw-1rem)]">
      {children}
    </PopoverContent>
  </Popover>;
}

function highlight(text: string, query: string) {
  const at = query ? text.toLowerCase().indexOf(query.toLowerCase()) : -1;
  if (at < 0) return <>{text}</>;
  return <>{text.slice(0, at)}<mark className="bg-transparent text-foreground underline underline-offset-2">{text.slice(at, at + query.length)}</mark>{text.slice(at + query.length)}</>;
}

/** The `@` file picker, ported from v2's `MentionPicker`: debounced search, one highlighted row, name over path. */
export function MentionPicker({ query, search, generation, onSelect, onDismiss }: {
  readonly query: string;
  readonly generation?: MentionsConfig['generation'];
  readonly search: MentionsConfig['search'];
  readonly onSelect: (path: string) => void;
  readonly onDismiss: () => void;
}) {
  const { labels } = useChatText();
  // Results are tagged with the search function that produced them: a binding switch hides the previous binding's rows at once.
  const [outcome, setOutcome] = useState<{ readonly search: MentionsConfig['search']; readonly results: readonly MentionResult[]; readonly failure: string | null }>();
  const shown = outcome?.search === search ? outcome : undefined;
  const results = shown?.results ?? [];
  const failure = shown?.failure ?? null;
  const [active, setActive] = useState(0);
  const list = useRef<HTMLUListElement>(null);
  const searcher = useRef(search); searcher.current = search;
  useEffect(() => {
    setActive(0);
    const abort = new AbortController();
    const timer = setTimeout(() => {
      searcher.current(query, abort.signal).then(found => { if (!abort.signal.aborted) setOutcome({ search, results: found.slice(0, 8), failure: null }); },
        cause => { if (!abort.signal.aborted) setOutcome({ search, results: [], failure: cause instanceof Error ? cause.message : labels.searchFailed }); });
    }, 120);
    return () => { clearTimeout(timer); abort.abort(); };
  }, [query, search, generation]);
  usePickerKeyboard({ count: results.length, activeIdx: active, setActiveIdx: setActive, listRef: list, onSelect: index => { const item = results[index]; if (item) onSelect(item.path); }, onDismiss });

  if (results.length === 0 && !failure) return null;
  return <ComposerSuggestions testId="mention-menu" onDismiss={onDismiss}>
    {failure ? <div role="alert" data-testid="mention-error" className="text-xs text-destructive">{failure}</div>
      : <ul ref={list} role="listbox" aria-label={labels.workspaceFiles} className="m-0 flex max-h-[min(14rem,40dvh)] list-none flex-col overflow-y-auto p-0">
        {results.map((item, index) => {
          const name = item.path.split('/').pop() ?? item.path;
          const Icon = item.kind === 'directory' ? FolderIcon : FileTextIcon;
          return <Item key={item.path} render={<li />} size="xs" variant={index === active ? 'muted' : 'default'} role="option" aria-selected={index === active} data-testid="mention-item" data-path={item.path} title={item.path}
            onMouseEnter={() => setActive(index)} onMouseDown={event => { event.preventDefault(); onSelect(item.path); }}
            className="cursor-pointer flex-nowrap max-sm:min-h-11 pointer-coarse:min-h-11">
            <ItemMedia variant="icon"><Icon aria-hidden="true" /></ItemMedia>
            <ItemContent className="min-w-0"><ItemTitle>{highlight(name, query)}</ItemTitle>
              <ItemDescription className="m-0 truncate">{item.path}</ItemDescription></ItemContent>
          </Item>;
        })}
      </ul>}
  </ComposerSuggestions>;
}

'use client';

import { useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import type { ImageContent, ToolResultMessage, UserMessage } from '@earendil-works/pi-ai';
import { AlertCircleIcon, CircleSlashIcon, FileIcon, FileSpreadsheetIcon, FileTextIcon, ImageIcon, PresentationIcon } from 'lucide-react';
import { CopyButton } from './code-block';
import { Markdown } from './markdown';
import type { CommandMentions } from './markdown';
import { ArtifactCard } from './artifact-card';
import type { ArtifactsConfig } from './artifact';
import { ApprovalCard } from './approval-card';
import { QuestionCard } from './question-card';
import type { AnswerOutcome } from './question-card';
import { ActivityBlock } from './activity';
import type { ActivityState } from './activity';
import { Shimmer } from './shimmer';
import { ToolCard } from './tool';
import { thumbnail } from './composer';
import { displayName, fileKind, isUploadPath, pieces, visibleParts } from './config';
import type { FileKind, Piece, PreviewRead } from './config';
import { isFileBlock, segments } from './rows';
import type { DeriveOptions, Row } from './rows';
import { Button } from '@/components/ui/button';
import { BlockActions } from '../button/actions';
import type { BlockAction } from '../button/actions';
import { useChatText } from './labels';
import type { ReplyRef } from './config';
import { Message, MessageContent, MessageFooter } from '@/components/ui/message';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Attachment, AttachmentContent, AttachmentDescription, AttachmentMedia, AttachmentTitle, AttachmentTrigger } from '@/components/ui/attachment';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';

export interface RowContext {
  readonly developer: boolean;
  readonly groupTool: DeriveOptions['groupTool'];
  readonly commandMentions: CommandMentions | undefined;
  readonly onOpenImage: ((image: ImageContent) => void) | undefined;
  readonly onCopy: ((text: string) => Promise<void>) | undefined;
  /** Which tokens of a sent message get a styled treatment (`@path` mentions, a leading `/skill`). */
  readonly pieces: { readonly mentions: boolean; readonly uploads?: boolean; readonly skills: readonly string[]; readonly openMention?: ((path: string) => void) | undefined; readonly renderMention?: ((path: string) => ReactNode | undefined) | undefined;
    readonly preview?: PreviewRead | undefined } | undefined;
  readonly fileChanges?: boolean | undefined;
  /** Opens a file card through the host's workspace opener. */
  readonly openFile?: ((path: string) => void) | undefined;
  readonly answer: ((questionId: string, answer: string) => Promise<AnswerOutcome>) | undefined;
  readonly artifacts: { readonly open: ArtifactsConfig['open']; readonly isOpen?: ArtifactsConfig['isOpen'] | undefined; readonly kinds?: ArtifactsConfig['kinds'] } | undefined;
  /** Replaces the default copy button under a settled reply (the ambient window adds feedback and the time); `host` holds the host's message actions. */
  readonly replyActions?: ((reply: { readonly key: string; readonly text: string; readonly timestamp?: number | undefined }, host: ReactNode) => ReactNode) | undefined;
  /** The host's actions for a settled reply (`messageActions`). */
  readonly messageActions?: ((reply: ReplyRef) => readonly BlockAction[]) | undefined;
  /** A line under a finished reply (not while it streams, runs a tool or waits to retry), after its actions (a host shows which model answered and how long it took). */
  readonly replyFooter?: ((reply: ReplyRef) => ReactNode) | undefined;
  /** Fork the conversation after a settled reply (its last native entry): adds a Fork button next to Copy. */
  readonly onFork?: ((entryId: string) => void) | undefined;
}

const replyRef = (row: Extract<Row, { type: 'assistant' }>): ReplyRef => ({ key: row.key, text: row.text, entryId: row.entryId, timestamp: row.timestamp, model: row.model, durationMs: row.durationMs });

function Image({ image, onOpenImage }: { readonly image: ImageContent; readonly onOpenImage: RowContext['onOpenImage'] }) {
  const { labels } = useChatText();
  const src = thumbnail(image.mimeType, image.data);
  return <Attachment orientation="vertical">
    <AttachmentMedia variant={src ? 'image' : 'icon'}>{src ? <img src={src} alt={labels.imageAttachment} /> : <ImageIcon aria-hidden="true" />}</AttachmentMedia>
    <AttachmentContent><AttachmentTitle>{labels.imageAttachment}</AttachmentTitle></AttachmentContent>
    <AttachmentTrigger data-testid="message-image" disabled={!onOpenImage} aria-label={labels.openImage} onClick={() => onOpenImage?.(image)} />
  </Attachment>;
}

/** A `@path` mention in a sent message: the host's own look when its `render` returns one, else the default chip (a button when it can be opened). */
function UserMention({ path, text, open, render }: { readonly path: string; readonly text: string; readonly open: ((path: string) => void) | undefined; readonly render: ((path: string) => ReactNode | undefined) | undefined }) {
  const custom = render?.(path);
  if (custom !== undefined) return <>{custom}</>;
  return open
    ? <Button variant="secondary" size="sm" data-testid="message-mention" data-path={path} aria-label={`Open ${path}`} onClick={() => open(path)}>{text}</Button>
    : <Badge variant="secondary" data-testid="message-mention" data-path={path}>{text}</Badge>;
}

/** The icon a file card shows for its kind. */
function FileGlyph({ kind }: { readonly kind: FileKind }) {
  switch (kind) {
    case 'image': return <ImageIcon aria-hidden="true" />;
    case 'sheet': return <FileSpreadsheetIcon aria-hidden="true" />;
    case 'slides': return <PresentationIcon aria-hidden="true" />;
    case 'document': return <FileTextIcon aria-hidden="true" />;
    default: return <FileIcon aria-hidden="true" />;
  }
}

/** A file a person sent (an `uploads/` mention): its icon or thumbnail, name and type. A button when it can be opened. */
function FileCard({ path, open, preview, change }: { readonly path: string; readonly open: ((path: string) => void) | undefined; readonly preview: PreviewRead | undefined; readonly change?: 'created' | 'edited' }) {
  const { labels } = useChatText();
  const kind = fileKind(path), name = change ? path.split('/').pop() || path : displayName(path);
  const [src, setSrc] = useState<string | undefined>();
  // A thumbnail belongs to the provider that read it: a new provider, or a read that is refused or unavailable, shows the icon.
  useEffect(() => {
    setSrc(undefined);
    if (kind !== 'image' || !preview) return;
    const abort = new AbortController();
    preview(path, abort.signal).then(
      read => { if (!abort.signal.aborted) setSrc(read ? thumbnail(read.mimeType, read.data) : undefined); },
      () => { if (!abort.signal.aborted) setSrc(undefined); });
    return () => abort.abort();
  }, [kind, path, preview]);
  return <Attachment className="max-w-64" {...(!open ? { 'data-testid': 'message-mention', 'data-path': path } : {})}>
    <AttachmentMedia variant={src ? 'image' : 'icon'}>{src ? <img src={src} alt="" /> : <FileGlyph kind={kind} />}</AttachmentMedia>
    <AttachmentContent>
      <AttachmentTitle>{name}</AttachmentTitle>
      <AttachmentDescription>{change ? labels.fileChange[change] : labels.fileKind[kind]}</AttachmentDescription>
    </AttachmentContent>
    {open && <AttachmentTrigger data-testid="message-mention" data-path={path} aria-label={labels.openFile(name)} onClick={() => open(path)} />}
  </Attachment>;
}

/** The file cards of a message, above its text bubble. */
function FileCards({ paths, open, preview }: { readonly paths: readonly string[]; readonly open: ((path: string) => void) | undefined; readonly preview: PreviewRead | undefined }) {
  return <ul data-testid="message-files" className="m-0 flex max-w-[85%] list-none flex-wrap justify-end gap-2 p-0">
    {paths.map(path => <li key={path} data-testid="message-file"><FileCard path={path} open={open} preview={preview} /></li>)}
  </ul>;
}

/**
 * A text part of a sent message. Its `uploads/` mentions become file cards above the bubble and leave the text; the message content keeps
 * them (only what is drawn changes).
 */
function UserText({ text, context }: { readonly text: string; readonly context: RowContext }) {
  const open = context.pieces?.openMention;
  const render = context.pieces?.renderMention;
  if (!context.pieces) return <Bubble variant="muted" align="end"><BubbleContent data-testid="user-text"><span className="whitespace-pre-wrap">{text}</span></BubbleContent></Bubble>;
  const all = pieces(text, context.pieces);
  const isFile = (piece: Piece) => piece.kind === 'mention' && isUploadPath(piece.value!);
  const files = all.filter(isFile).map(piece => piece.value!);
  const shown = files.length ? visibleParts(all, isFile) : all;
  const empty = shown.every(piece => piece.kind === undefined && piece.text === '');
  return <>
    {files.length > 0 && <FileCards paths={files} open={context.openFile ?? open} preview={context.pieces.preview} />}
    {!(files.length > 0 && empty) && <Bubble variant="muted" align="end"><BubbleContent data-testid="user-text"><span className="whitespace-pre-wrap">{shown.map((piece, at) => piece.kind === 'mention'
      ? <UserMention key={at} path={piece.value!} text={piece.text} open={open} render={render} />
      : piece.kind === 'skill' ? <Badge key={at} variant="secondary" data-testid="message-skill" data-skill={piece.value}>{piece.text}</Badge>
      : piece.text)}</span></BubbleContent></Bubble>}
  </>;
}

function UserBubble({ message, context }: { readonly message: UserMessage; readonly context: RowContext }) {
  const parts = typeof message.content === 'string' ? [{ type: 'text' as const, text: message.content }] : message.content;
  return <Message align="end"><MessageContent>
    {parts.map((part, index) => part.type === 'text' ? (isFileBlock(part.text) ? null : <UserText key={index} text={part.text} context={context} />)
      : <Image key={index} image={part} onOpenImage={context.onOpenImage} />)}
  </MessageContent></Message>;
}

function Notice({ tone, icon, children, testid }: { readonly tone: 'error' | 'muted'; readonly icon: ReactNode; readonly children: ReactNode; readonly testid: string }) {
  return <Alert variant={tone === 'error' ? 'destructive' : 'default'} role={tone === 'error' ? 'alert' : 'status'} data-testid={testid}>
    {icon}<AlertDescription>{children}</AlertDescription>
  </Alert>;
}

function resultText(message: ToolResultMessage): string { return message.content.map(part => part.type === 'text' ? part.text : '').join('\n'); }

export function RowView({ row, context: liveContext }: { readonly row: Row; readonly context: RowContext }) {
  const context: RowContext = row.historical ? { ...liveContext, answer: undefined, onFork: undefined, messageActions: undefined, replyActions: undefined, commandMentions: undefined } : liveContext;
  const { labels, icons } = useChatText();
  switch (row.type) {
    case 'user': return <article data-row-id={row.key} data-role="user" aria-live={row.historical ? 'off' : undefined}><UserBubble message={row.message} context={context} /></article>;
    case 'card': return <article data-row-id={row.key} data-role="event">{row.card.content}</article>;
    case 'event': return <article data-row-id={row.key} data-role="event" className="text-center text-xs text-muted-foreground">{labels.event(row.label)}</article>;
    case 'system': return <article data-row-id={row.key} data-role="system"><Collapsible>
      <CollapsibleTrigger render={<Button variant="ghost" />}>{labels.systemContext}</CollapsibleTrigger>
      <CollapsibleContent><pre className="whitespace-pre-wrap">{row.text}</pre></CollapsibleContent>
    </Collapsible></article>;
    case 'orphan-result': return <article data-row-id={row.key} data-role="toolResult"><Notice tone="error" testid="tool-error" icon={<AlertCircleIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>
      <strong className="font-semibold">{labels.toolFailed(row.message.toolName)}</strong><span className="mt-1 block font-mono text-xs whitespace-pre-wrap">{resultText(row.message)}</span></Notice></article>;
    case 'assistant': {
      const settled = !row.streaming;
      const files = new Map<string, 'created' | 'edited'>();
      if (context.fileChanges) for (const part of row.parts) {
        if (part.kind !== 'tool' || part.entry.status !== 'completed') continue;
        const { call, result } = part.entry;
        const path = call.arguments['path'];
        if (!result || result.isError || result.toolName !== call.name || (call.name !== 'write' && call.name !== 'edit') || typeof path !== 'string' || !path.trim()) continue;
        const normalized = path.replace(/^(\.\/)+/, '');
        if (normalized) files.set(normalized, files.get(normalized) === 'created' || call.name === 'write' ? 'created' : 'edited');
      }
      const chunks = segments(row.parts, context.groupTool);
      const active = row.active === true || row.streaming;
      const lastText = [...row.parts].reverse().find(part => part.kind === 'text');
      const host = settled && row.text && context.messageActions
        ? <BlockActions iconOnly actions={context.messageActions(replyRef(row))} testId="reply-action" menuLabel={labels.moreActions} />
        : null;
      return <article data-row-id={row.key} data-role="assistant" aria-live={row.historical ? 'off' : undefined} data-streaming={row.streaming ? 'true' : undefined} className="group/message">
        <Message><MessageContent>
        <div className="flex flex-col gap-3">
          {chunks.map((chunk, at) => {
            if (chunk.kind === 'activity') {
              const failed = chunk.steps.some(step => step.kind === 'tool' && step.entry.status === 'failed');
              const unfinished = chunk.steps.some(step => step.kind === 'tool' && step.entry.status === 'unfinished');
              const state: ActivityState = failed || row.stopReason === 'error' ? 'failed' : row.stopReason === 'aborted' || (!active && unfinished) ? 'stopped' : active && at === chunks.length - 1 ? 'running' : 'done';
              return <ActivityBlock key={chunk.key} steps={chunk.steps} state={state} streaming={row.streaming} developer={context.developer} {...(context.onOpenImage ? { onOpenImage: context.onOpenImage } : {})} />;
            }
            const part = chunk.part;
            if (part.kind === 'text') return <Bubble key={part.key} variant="ghost"><BubbleContent><Markdown text={part.text} streaming={row.streaming && part === lastText && row.parts[row.parts.length - 1] === part}
              {...(settled && context.commandMentions ? { commandMentions: context.commandMentions } : {})} {...(context.onCopy ? { onCopy: context.onCopy } : {})} /></BubbleContent></Bubble>;
            if (part.kind === 'thinking') return null; // reasoning is a step of an activity block
            if (part.kind === 'approval') return <ApprovalCard key={part.key} call={part.call} result={part.result} questionId={part.questionId} answer={context.answer} summary={part.summary} decision={part.decision} live={part.live} />;
            if (part.kind === 'question') return <QuestionCard key={part.key} call={part.call} result={part.result} questionId={part.questionId} answer={context.answer} live={part.live} />;
            if (part.kind === 'artifact' && part.artifact && files.has(part.artifact.target.resource.path.replace(/^(\.\/)+/, ''))) return null;
            if (part.kind === 'artifact') return <ArtifactCard key={part.key} artifact={part.artifact} title={part.title} {...(part.state === 'ready' ? {} : { pending: part.state })}
              open={part.artifact !== undefined && (context.artifacts?.isOpen?.(part.artifact) ?? false)} onOpen={context.artifacts?.open} kinds={context.artifacts?.kinds} />;
            return part.entry.custom ? <div key={part.key}>{part.entry.custom}</div> : <ToolCard key={part.key} entry={part.entry} {...(context.onOpenImage ? { onOpenImage: context.onOpenImage } : {})} />;
          })}
          {files.size > 0 && <ul data-testid="reply-files" className="m-0 flex list-none flex-wrap gap-2 p-0">
            {[...files].map(([path, change]) => <li key={path} data-testid="message-file"><FileCard path={path} change={change} open={context.openFile} preview={context.pieces?.preview} /></li>)}
          </ul>}
          {row.streaming && row.parts.length === 0 && <p data-testid="working" className="m-0 text-sm"><Shimmer>{labels.thinking}</Shimmer></p>}
        </div>
        {row.stopReason === 'error' && <Notice tone="error" testid="response-error" icon={<AlertCircleIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>{row.errorMessage ?? labels.responseFailed}</Notice>}
        {row.stopReason === 'aborted' && <Notice tone="muted" testid="interrupted" icon={<CircleSlashIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>{labels.interrupted}</Notice>}
        {settled && row.text && context.replyActions?.({ key: row.key, text: row.text, timestamp: row.timestamp }, host)}
        {settled && row.text && !context.replyActions && <div className="mt-1 -ml-2 flex opacity-0 transition-opacity group-focus-within/message:opacity-100 group-hover/message:opacity-100 pointer-coarse:opacity-100 max-sm:opacity-100 motion-reduce:transition-none">
          <CopyButton iconOnly text={row.text} label={labels.copyResponse} {...(context.onCopy ? { onCopy: context.onCopy } : {})} />
          {context.onFork && row.entryId && <Button size="icon-sm" variant="ghost" aria-label={labels.fork} title={labels.forkHint} data-testid="fork-reply"
            onClick={() => context.onFork!(row.entryId!)}><icons.fork data-icon="inline-start" aria-hidden="true" /></Button>}
          {host}</div>}
        {settled && !row.active && row.text && context.replyFooter && <MessageFooter>{context.replyFooter(replyRef(row))}</MessageFooter>}
        </MessageContent></Message>
      </article>;
    }
  }
}

